import {collapseArt} from './collapse-art.js';
import {HEROES,ENEMIES} from './engine.js';
import {NEW_ART} from './condition-ui.js';
import {castArt,ART_ROLES} from './cast-art.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const ALLIES=Object.entries(HEROES).flatMap(([hero,h])=>[{id:hero,hero,name:h.name,partner:false},{id:h.partner,hero,name:h.partnerName,partner:true}]);
export function galleryItems(hero,partner=false){const h=HEROES[hero];if(partner)return [{id:'standing',name:'스탠딩',src:castArt(hero,'partner')},{id:'support',name:'파트너 지원',src:castArt(hero,'support'),animation:'support'},{id:'partner-card',name:'지원 카드 일러스트',src:`${NEW_ART}partner-cards/${h.partner}.webp`}];
 return [{id:'standing',name:'스탠딩',src:castArt(hero,'portrait'),variants:[{id:'normal',name:'기본',src:castArt(hero,'portrait')},{id:'collapse',name:'붕괴',src:castArt(hero,'breakdownPortrait')}]},...[1,2].map(stage=>({id:'breakdown-'+stage,name:'붕괴 '+stage+'단계 컷인',src:collapseArt(hero,stage),animation:'breakdown',stage})),...['ultimate','portraitCutin'].map(role=>({id:role,name:ART_ROLES[role],src:castArt(hero,role),animation:['ultimate','breakdown'].includes(role)?role:null})),...['eye','arm','leg'].map((part,i)=>({id:part,name:['눈 결손','팔 결손','다리 결손'][i],src:`${NEW_ART}injuries/${hero}/${part}-cutin.webp`,animation:'injury-'+['eyes','leftArm','leftLeg'][i]}))];
}
export function allyRail(selected=null){return `<div class="ally-archive-rail" data-drag-scroll tabindex="0" aria-label="아군 목록 · 드래그해서 이동">${ALLIES.map(a=>`<button class="${selected===a.id?'selected':''}" style="--accent:${HEROES[a.hero].color}" data-action="codex-ally" data-entity="${a.id}" aria-label="${a.name} 상세정보"><figure class="archive-standing"><img src="${NEW_ART}standing/${a.id}.webp" alt="${a.name}" draggable="false"></figure><span>${a.name}<small>${a.partner?'파트너 · '+HEROES[a.hero].name:HEROES[a.hero].role}</small></span></button>`).join('')}</div>`;}
export function galleryMarkup(entity){const a=ALLIES.find(a=>a.id===entity);return `<div class="illustration-folders">${galleryItems(a.hero,a.partner).map(item=>`<details class="illustration-folder"><summary><img src="${item.src}" alt="${esc(item.name)} 미리보기"><span>${esc(item.name)}</span></summary><div>${`<button data-action="art-large" data-entity="${a.id}" data-art="${item.id}">확대</button>`}${item.animation?`<button data-action="replay-cutin" data-hero="${a.hero}" data-kind="${item.animation}" ${item.stage?`data-stage="${item.stage}"`:''}>연출</button>`:''}</div></details>`).join('')}</div>`;}
export function injuryEffects(h){const b=h.body,list=[];if(b.eyes===2)list.push('눈 중상 · 전용 카드 블러');if(b.eyes===3)list.push('눈 결손 · 실명 카드로 변경');const arms=[b.leftArm,b.rightArm].filter(n=>n>=2).length,lostArms=[b.leftArm,b.rightArm].filter(n=>n===3).length,legs=[b.leftLeg,b.rightLeg].filter(n=>n>=2).length,lostLegs=[b.leftLeg,b.rightLeg].filter(n=>n===3).length;if(arms)list.push(`팔 · 카드 수치 효과 -${arms*20}%`);if(lostArms)list.push(`팔 결손 · 드로우 효과 -${lostArms}`);if(legs)list.push(`다리 · 타 부위 부상 위험 +${legs*15}%p`);if(lostLegs)list.push(`다리 결손 · 받는 피해 +${lostLegs*25}%`);if(h.retired)list.push('거점 치료 전까지 이탈 · 파트너 지원 유지');return list;}
